{
  "schema": "mosio.recipe/1",
  "id": "kinetic-typography",
  "title": "Kinetic typography",
  "description": "Short lines of big type where every word lands on its own beat, one scene per line, with one accent word per line. For hooks, quotes and slogans.",
  "version": "0.1.0",
  "tags": [
    "typography",
    "social",
    "text"
  ],
  "license": "MIT",
  "provenance": {
    "authors": [
      "Mosio"
    ],
    "sources": [
      {
        "kind": "own",
        "name": "fixtures/w1-kinetic",
        "path": "fixtures/w1-kinetic",
        "what": "staggered word entrances on one baseline bar; re-authored as WAAPI/CSS scenes, one per line"
      }
    ]
  },
  "formats": [
    {
      "ratio": "9:16",
      "width": 1080,
      "height": 1920,
      "fps": 30,
      "vars": {
        "fs_display": 150,
        "fs_body": 104,
        "margin": 96
      }
    },
    {
      "ratio": "16:9",
      "width": 1920,
      "height": 1080,
      "fps": 30,
      "vars": {
        "fs_display": 150,
        "fs_body": 112,
        "margin": 100
      }
    }
  ],
  "duration_s": {
    "min": 6,
    "default": 12,
    "max": 40
  },
  "beats": {
    "roles": [
      "hook",
      "fact",
      "step",
      "payoff",
      "cta"
    ],
    "min": 2,
    "max": 7,
    "tempo_s": {
      "short": 1.6,
      "medium": 2.4,
      "long": 3.2
    },
    "ending_min_s": 1.5
  },
  "plan": [
    {
      "roles": [
        "hook",
        "payoff"
      ],
      "scene": "scenes/hook.html",
      "technique": "one word per line at display size, accent word and a bar that draws in",
      "primitives": [
        "rise-fade",
        "bar-draw"
      ],
      "limits": {
        "max_words": 4
      }
    },
    {
      "roles": [
        "fact",
        "step"
      ],
      "scene": "scenes/line.html",
      "technique": "words flow left to right on wrapped lines with a running scene number",
      "primitives": [
        "rise-fade"
      ],
      "limits": {
        "max_words": 9
      }
    },
    {
      "roles": [
        "cta"
      ],
      "scene": "scenes/cta.html",
      "technique": "centred words, accent pill that grows under the whole line",
      "primitives": [
        "rise-fade",
        "pill-grow"
      ],
      "limits": {
        "max_words": 6
      }
    }
  ],
  "transitions": {
    "default": {
      "kind": "crossfade",
      "frames": 12
    }
  },
  "derive": [
    {
      "as": "pace",
      "from": "/style/pacing",
      "map": {
        "calm": 1.3,
        "medium": 1,
        "brisk": 0.75
      }
    },
    {
      "as": "text_case",
      "from": "/style/case",
      "map": {
        "upper": "uppercase",
        "as-typed": "none"
      }
    }
  ],
  "controls": [
    {
      "param": "/style/brand/accent",
      "label": "Accent colour",
      "effect": "Recolours the accent word, bar and pill: --accent in shared/tokens.css, so every scene re-renders."
    },
    {
      "param": "/style/font_scale",
      "label": "Type size",
      "effect": "Scales all type: --type-scale in shared/tokens.css."
    },
    {
      "param": "/style/pacing",
      "label": "Pacing",
      "effect": "Speeds or slows each word's entrance: --pace in shared/tokens.css."
    },
    {
      "param": "/content/beats/0/text",
      "label": "Line text",
      "effect": "Edit the words of one beat directly in its scene file; only that scene re-renders."
    }
  ],
  "inputs": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "name": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9-]{1,39}$",
        "default": "kinetic-typography",
        "description": "Project name written to mosio.json."
      },
      "format": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Output size and length.",
        "properties": {
          "ratio": {
            "enum": [
              "9:16",
              "16:9"
            ],
            "default": "9:16",
            "description": "Aspect ratio: 9:16 vertical for social, 16:9 landscape."
          },
          "duration_s": {
            "type": "number",
            "minimum": 6,
            "maximum": 40,
            "default": 12,
            "description": "Total length in seconds after transitions. Beats share it by weight."
          }
        }
      },
      "content": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "What the video says.",
        "properties": {
          "beats": {
            "type": "array",
            "minItems": 2,
            "maxItems": 7,
            "default": [
              {
                "role": "hook",
                "text": "Kinetic type",
                "key": "type"
              },
              {
                "role": "fact",
                "text": "Moves every word",
                "key": "Moves"
              },
              {
                "role": "fact",
                "text": "In sync with time",
                "key": "time"
              },
              {
                "role": "step",
                "text": "Rendered frame by frame",
                "key": "frame"
              },
              {
                "role": "cta",
                "text": "Straight to MP4",
                "key": "MP4"
              }
            ],
            "description": "One entry per scene, in order. Each beat is a short line; every word enters on its own.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "role",
                "text"
              ],
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9-]{0,23}$",
                  "description": "Optional scene id (used in every data-mosio-id). Defaults to the role name; a repeated role gets -2, -3."
                },
                "role": {
                  "enum": [
                    "hook",
                    "fact",
                    "step",
                    "payoff",
                    "cta"
                  ],
                  "description": "What this beat does in the story; picks the scene template."
                },
                "text": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 60,
                  "description": "The words on screen, written literally into the scene HTML."
                },
                "key": {
                  "type": "string",
                  "maxLength": 40,
                  "description": "The word or words of the text to stress with the accent colour. Must occur in the text."
                },
                "weight": {
                  "enum": [
                    "short",
                    "medium",
                    "long"
                  ],
                  "default": "medium",
                  "description": "Relative screen time of this beat."
                }
              }
            }
          }
        }
      },
      "style": {
        "type": "object",
        "additionalProperties": false,
        "default": {},
        "description": "Look: brand colours, type size and motion speed.",
        "properties": {
          "brand": {
            "type": "object",
            "additionalProperties": false,
            "description": "Brand colours. They are written to shared/tokens.css, so changing one re-renders every scene.",
            "default": {},
            "properties": {
              "bg": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Background colour of every scene (--bg in shared/tokens.css).",
                "default": "#0f172a"
              },
              "main": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Main brand colour: large shapes and the key surface (--main).",
                "default": "#38bdf8"
              },
              "accent": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Accent colour for the one thing that matters on screen: key word, winner bar, price (--accent).",
                "default": "#f59e0b"
              },
              "text": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Text colour on the background (--text).",
                "default": "#f8fafc"
              },
              "text_on_accent": {
                "type": "string",
                "pattern": "^#[0-9a-fA-F]{6}$",
                "description": "Text colour used on top of the accent colour, for example on a button (--text-on-accent).",
                "default": "#0f172a"
              }
            }
          },
          "font_scale": {
            "type": "number",
            "minimum": 0.6,
            "maximum": 1.25,
            "default": 1,
            "description": "Multiplier on every type size (--type-scale). 1 is the designed size; check `mosio inspect` for overflow above 1."
          },
          "pacing": {
            "enum": [
              "calm",
              "medium",
              "brisk"
            ],
            "default": "medium",
            "description": "Speed of the motion inside each scene: calm slows entrances by about 30 percent, brisk speeds them by about 25 percent. Scene lengths do not change."
          },
          "case": {
