  },
  "files": {
    "scenes": [
      "scenes/hook.html",
      "scenes/line.html",
      "scenes/cta.html"
    ],
    "shared": [
      "shared/tokens.css",
      "shared/base.css"
    ],
    "fonts": [
      "Inter-Regular.otf",
      "Inter-Bold.otf",
      "Inter-ExtraBold.otf"
