  },
  "example": {
    "project": "example/",
    "params": "example.params.json"
  },
  "engine": {
    "libraries": []
  },
  "requires": [],
  "checks": {
    "min_text_px": 64,
    "max_words_on_screen": 9,
    "max_font_families": 1
